/**
 * Browser-side admin bundle entry point.
 *
 * Bundled by esbuild (pnpm build:admin):
 *   src/admin-client.ts → public/admin/bundle.js
 *
 * The bare, non-contentia Decap app and every registration (backends, widgets,
 * locales) come from src/cms.ts — generated by the `contentia create` wizard.
 * This entry supplies the site's config and explicitly mounts the bare app.
 */
import { init } from './cms.js';
import { blogCollections } from './decap-config.js';

init({
  config: {
    // The complete config is inline; do not also fetch /admin/config.yml.
    load_config_file: false,
    backend: {
      name: 'laika',
      base_url: typeof window !== 'undefined' ? window.location.origin : 'http://localhost:3000',
      api_root: '/api/decap',
      dev_token: 'dev-local-contentia-token',
    },
    media_folder: 'public/uploads',
    public_folder: '/uploads',
    collections: blogCollections,
  } as any,
});
